"""Cherry Pickup — two walkers moving forward simultaneously.

A round trip is equivalent to two paths from (0,0) to (n-1,n-1). Both walkers
take the same number of steps, so the state is (step, row1, row2) and the shared
cell is only counted once.

Time: O(n^3)   Space: O(n^2)
"""
from typing import List


class Solution:
    def cherryPickup(self, grid: List[List[int]]) -> int:
        n = len(grid)
        NEG = float("-inf")
        dp = [[NEG] * n for _ in range(n)]
        dp[0][0] = grid[0][0]

        for step in range(1, 2 * n - 1):
            nxt = [[NEG] * n for _ in range(n)]
            for r1 in range(max(0, step - n + 1), min(n, step + 1)):
                c1 = step - r1
                if grid[r1][c1] == -1:
                    continue
                for r2 in range(r1, min(n, step + 1)):
                    c2 = step - r2
                    if c2 < 0 or grid[r2][c2] == -1:
                        continue
                    best = NEG
                    for p1 in (r1, r1 - 1):
                        for p2 in (r2, r2 - 1):
                            if 0 <= p1 < n and 0 <= p2 < n:
                                best = max(best, dp[p1][p2])
                    if best == NEG:
                        continue
                    gain = grid[r1][c1] + (grid[r2][c2] if r1 != r2 else 0)
                    nxt[r1][r2] = best + gain
            dp = nxt
        return max(0, dp[n - 1][n - 1])
